@@ -0,0 +1,14 @@
+import { AppError } from "../errors.js";
+
+/** Whether a location belongs to the store's selected site (main by default). */
+export function inSite(store, location) {
+  return store.data.locations.some((l) => l.id === location && l.site === (store.site ?? "main"));
+}
+
+/** Creates a request-local store context, preserving shared data and persistence. */
+export function forSite(store, site) {
+  if (!store.data.sites.some((s) => s.id === site)) throw new AppError("unknown_site", { id: site });
+  const context = Object.create(store);
+  context.site = site;
+  return context;
+}
