diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..9acacaa
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,64 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const headers = { "X-Larder-Site": "annex" };
+
+test("site headers default to main, reject unknown sites and preserve shared catalogues", async () => {
+  const { handle } = app();
+  const unknown = await handle({ path: "/items", headers: { "x-larder-site": "missing" } });
+  assert.equal(unknown.status, 400);
+  assert.equal(unknown.body.error.code, "unknown_site");
+  const main = (await handle({ path: "/items/1" })).body;
+  const annex = (await handle({ path: "/items/1", headers })).body;
+  assert.equal(main.onHand, 10);
+  assert.equal(annex.onHand, 0);
+  assert.deepEqual(annex.batches, []);
+  assert.equal(main.name, annex.name);
+  for (const path of ["/suppliers", "/dishes", "/recipes/1/cost"]) {
+    assert.deepEqual(await handle({ path, headers }), await handle({ path }));
+  }
+});
+
+test("batch access, cooking, alerts and value use only the selected site", async () => {
+  const { store, handle } = app();
+  store.data.batches.push({ ...store.data.batches[0], id: store.nextId("batch"), location: "annex-fridge", qty: 2 });
+  assert.equal((await handle({ path: "/batches", headers })).body.length, 1);
+  assert.equal((await handle({ path: "/batches/1", headers })).status, 404);
+  const before = structuredClone(store.data);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers, body: { qty: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers, body: { portions: 4 } })).status, 409);
+  assert.deepEqual(store.data, before);
+  const value = (await handle({ path: "/reports/stock-value", headers })).body;
+  assert.equal(value.totalCents, 360);
+  const alerts = (await handle({ path: "/alerts", headers })).body;
+  assert.ok(alerts.expiring.every((b) => b.location === "annex-fridge"));
+  assert.equal(alerts.lowStock.find((i) => i.itemId === 1).qty, 2);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+});
+
+test("stock-takes and receiving reject locations and ids from another site", async () => {
+  const { store, handle } = app();
+  const post = (path, body, selected = headers) => handle({ method: "POST", path, body, headers: selected });
+  assert.equal((await post("/stocktakes", { location: "fridge" })).body.error.code, "unknown_location");
+  const take = (await post("/stocktakes", { location: "annex-fridge" })).body;
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId: 1, counted: 1 })).status, 404);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {}, {})).status, 404);
+  const before = structuredClone(store.data);
+  const received = await post("/orders/2/receive", { lots: [
+    { lot: "a", expires: null, location: "annex-fridge" },
+    { lot: "b", expires: null, location: "fridge" },
+  ] });
+  assert.equal(received.body.error.code, "unknown_location");
+  assert.deepEqual(store.data, before);
+  const result = await post("/orders/2/receive", { lots: [
+    { lot: "a", expires: null, location: "annex-fridge" },
+    { lot: "b", expires: null, location: "annex-fridge" },
+  ] });
+  assert.equal(result.status, 200);
+  const batchId = result.body.batches[0].id;
+  assert.equal((await post(`/stocktakes/${take.id}/counts`, { batchId, counted: 3 })).status, 200);
+  assert.equal((await post(`/stocktakes/${take.id}/finish`, {})).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === batchId).qty, 3);
+  assert.equal((await handle({ path: `/batches/${batchId}` })).status, 404);
+});
